const Vector3 &n = p.GetNormal();
Validate((float)n.X() == 1.0f && (float)n.Y() == 2.0f && (float)n.Z() == 3.0f);



SetFunctionName("GetNormal() const");

Plane p;
p.Set(1.0f, 2.0f, 3.0f, 4.0f);
