SetFunctionName("Mask4 CompLessThan(Plane a, Plane b)");
Plane va(1.0f, 1.0f, 2.0f, 2.0f );
Plane vb(1.0f, 2.0f, 1.0f, -1.0f );

Mask4 mask(CompLessThan(va, vb));
Validate(
    !mask.GetX().GetBool() &&
     mask.GetY().GetBool() &&
    !mask.GetZ().GetBool() &&
    !mask.GetW().GetBool()
);



SetFunctionName("Mask4 CompGreaterThan(Plane a, Plane b)");
