SetFunctionName("Plane Select(MaskScalar mask, Plane a, Plane b)");
Plane v1(1.0f, 2.0f, 3.0f, 4.0f);
Plane v2(10.0f, 20.0f, 30.0f, 40.0f);

Plane result1 = Select( MaskScalar(true), v1, v2 );
Plane result2 = Select( MaskScalar(false), v1, v2 );
Validate(
    result1 == v1 &&
    result2 == v2
);


#ifdef HOST_TESTING
        SetFunctionName("Plane Select(MaskScalar mask, Plane a, Plane b)");
        Plane v1(1.0f, 2.0f, 3.0f, 4.0f);
        Plane v2(-10.0f, -20.0f, -30.0f, -40.0f);
        Plane ref1( -1.0f, 20.0f, -3.0f, -40.0f);

        uint32_t values[] = { 0x7fffffff, 0x80000000, 0x7fffffff, 0x00000000 };
        Mask4 mask(values[0], values[1], values[2], values[3]);

        Plane result1 = Select( mask, v1, v2 );
        Validate( result1 == ref1 );
#endif



SetFunctionName("Plane Select(Mask4 mask, Plane a, Plane b)");
Plane v1(1.0f, 2.0f, 3.0f, 4.0f);
Plane v2(10.0f, 20.0f, 30.0f, 40.0f);
Plane ref1(1.0f, 2.0f, 30.0f, 40.0f);
Plane ref2(10.0f, 20.0f, 3.0f, 4.0f);
Mask4 mask1(true, true, false, false);
Mask4 mask2(false, false, true, true);

Plane result1 = Select( mask1, v1, v2 );
Plane result2 = Select( mask2, v1, v2 );
Validate(
    result1 == ref1 &&
    result2 == ref2
);



