SetFunctionName("IntersectPlaneLine(const Plane &plane,const Vector3 &p0,const Vector3 &p1,Vector3 &impact_out)");

// Testing IntersectPlaneLine
Vector3 VectorA1, VectorB1, VectorC1, VectorD1;
Plane PlaneA1;
// plane w/ normal (1,0,0) and d=3 sets origin at (-3, 0, 0)
PlaneA1.Set(1, 0, 0, 3);
VectorA1.Set(0, 0, 0);
VectorB1.Set(0, 1, 0);
VectorC1.Set(5, 1, 0);
VectorD1.Set( -3, 1, 0);
PlaneIntersection piResult1 = IntersectPlaneLine(PlaneA1, VectorB1, VectorC1, VectorA1);

// testing line parallel to plane where the line is not on the plane
Vector3 VectorA2, VectorB2, VectorC2, VectorD2;
Plane PlaneA2;
PlaneA2.Set(1, 0, 0, 3);
VectorA2.Set(0, 0, 0);
VectorB2.Set(0, -3, 0);
VectorC2.Set(0, -3, 1);
VectorD2.Set(0, 0, 0);
PlaneIntersection piResult2 = IntersectPlaneLine(PlaneA2, VectorB2, VectorC2, VectorA2);

// testing line parallel to plane where the line is on the plane
Vector3 VectorA3, VectorB3, VectorC3, VectorD3;
Plane PlaneA3;
PlaneA3.Set(1, 0, 0, 3);
VectorA3.Set(0, 0, 0);
VectorB3.Set(-3, 0, 0);
VectorC3.Set(-3, 0, 1);
VectorD3.Set(0, 0, 0);
PlaneIntersection piResult3 = IntersectPlaneLine(PlaneA3, VectorB3, VectorC3, VectorA3);

Validate( piResult1 == PI_ONE && IsSimilar(VectorA1, VectorD1) &&
          piResult2 == PI_ZERO &&
          piResult3 == PI_INFINITY );



SetFunctionName("IntersectPlaneDirectedSegment(const Plane &plane,const Vector3 &p0,const Vector3 &p1,Vector3 &impact_out)");

// Testing IntersectPlaneDirectedSegment
Vector3 VectorA, VectorB, VectorC, VectorD;
Plane PlaneA;
// plane w/ normal (1,0,0) and d= -3 sets origin at (3, 0, 0)
PlaneA.Set(1, 0, 0, -3);
VectorA.Set( 0, 0, 0);
VectorB.Set( 0, 1, 0);
VectorC.Set( 5, 1, 0);
VectorD.Set( 3, 1, 0);
PlaneIntersection piResult1 = IntersectPlaneDirectedSegment(PlaneA, VectorB, VectorC, VectorA);

// testing line parallel to plane where the line is not on the plane
Vector3 VectorA2, VectorB2, VectorC2, VectorD2;
Plane PlaneA2;
PlaneA2.Set(1, 0, 0, 3);
VectorA2.Set(0, 0, 0);
VectorB2.Set(0, -3, 0);
VectorC2.Set(0, -3, 1);
VectorD2.Set(0, 0, 0);
PlaneIntersection piResult2 = IntersectPlaneLine(PlaneA2, VectorB2, VectorC2, VectorA2);

// testing line parallel to plane where the line is on the plane
Vector3 VectorA3, VectorB3, VectorC3, VectorD3;
Plane PlaneA3;
PlaneA3.Set(1, 0, 0, 3);
VectorA3.Set(0, 0, 0);
VectorB3.Set(-3, 0, 0);
VectorC3.Set(-3, 0, 1);
VectorD3.Set(0, 0, 0);
PlaneIntersection piResult3 = IntersectPlaneLine(PlaneA3, VectorB3, VectorC3, VectorA3);

Validate( piResult1 == PI_ONE && IsSimilar(VectorA, VectorD) &&
          piResult2 == PI_ZERO &&
          piResult3 == PI_INFINITY );



